use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm;

struct Node;

/// Maximum rounds of the tool-orchestration loop before we give up. Bounds the
/// loop so a model that never stops asking for tools cannot hang the node.
const MAX_ROUNDS: usize = 8;

/// The one tool this node is wired for: `LLMClient<[lookup]>` plus the
/// read-only knowledge-base handle. The scope is `lookup` and nothing else.
const LOOKUP_TOOL: &str = "lookup";

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // `requires len(question) <= 512` holds of every input; a well-formed
        // graph never hands us a longer one. We neither depend on violating it
        // nor try to widen it here.
        let system = "You are a customer support agent. Answer the user's \
                      question using the provided knowledge. If you need more \
                      information, you may request the `lookup` tool.";

        let mut prompt = String::new();
        prompt.push_str("Question:\n");
        prompt.push_str(&ctx.question);

        if !ctx.knowledge.is_empty() {
            prompt.push_str("\n\nKnowledge:\n");
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
        }

        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(system, &prompt) {
                tool_llm::Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                tool_llm::Reply::Call(req) => {
                    // The only authority this node holds is the read-only KB
                    // lookup. Any other tool the model names is simply not
                    // something we can invoke — there is no import for it.
                    if req.tool == LOOKUP_TOOL {
                        let results = kb_read::lookup(&req.query);
                        prompt.push_str("\n\nLookup results for \"");
                        prompt.push_str(&req.query);
                        prompt.push_str("\":\n");
                        if results.is_empty() {
                            prompt.push_str("(no results)\n");
                        } else {
                            for r in &results {
                                prompt.push_str("- ");
                                prompt.push_str(r);
                                prompt.push('\n');
                            }
                        }
                    } else {
                        prompt.push_str("\n\nTool \"");
                        prompt.push_str(&req.tool);
                        prompt.push_str("\" is not available; answer directly.\n");
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool orchestration did not converge on an answer".to_string(),
        })
    }
}

export!(Node);
```

